// @vitest-environment node
/**
 * Golden URLs: `__fixtures__/image-golden.jsonl` was generated by running v8
 * storefronts' own image helpers, unchanged (the vendored v7
 * `getOptimizedMediaUrl` / `getSrcSet` copies and two next/image loaders),
 * over the platform-neutral sources (Deco asset hosts, other hosts, paths,
 * data: URIs, ""). Each config below is the `decoCdn` a site uses, and must
 * reproduce its URLs byte for byte: no case changes. The commerce platforms'
 * cases live with their providers (`@decocms/apps-vtex/image`,
 * `@decocms/apps-shopify/image`).
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  createImageUrl,
  decoCdn,
  type ImageUrl,
  parseSrcSet,
  preloadLink,
  type ResizeOptions,
  srcSet,
} from "./image.ts";

interface Case {
  config: string;
  call: "url" | "srcSet" | "isOptimizable";
  src: string;
  opts?: ResizeOptions & { widths?: number[]; factors?: number[] };
  expected: string | boolean | null;
}

const cases: Case[] = readFileSync(
  new URL("./__fixtures__/image-golden.jsonl", import.meta.url),
  "utf-8",
)
  .split("\n")
  .filter(Boolean)
  .map((line) => JSON.parse(line));

/** The next/image loaders: Deco CDN at "high", contain, quality last. */
const nextLoader = createImageUrl({
  providers: [decoCdn({ quality: "high", fit: "contain", layout: "quality-last" })],
});

const CONFIGS: Record<string, ImageUrl> = {
  "tanstack-decoims-high": createImageUrl({
    providers: [decoCdn({ domain: "decoims.com", quality: "high", sources: "all" })],
  }),
  "tanstack-default": createImageUrl({ providers: [decoCdn({ sources: "all" })] }),
  "tanstack-anchored": createImageUrl({
    providers: [decoCdn({ sources: "all", stripAssetHosts: "leading" })],
  }),
  "next-thumbor": nextLoader,
  "next-query": nextLoader,
};

function run(c: Case): string | boolean | null {
  const url = CONFIGS[c.config];
  if (c.call === "isOptimizable") return url.isOptimizable(c.src);
  if (c.call === "srcSet") return srcSet(url, c.src, c.opts ?? {}) ?? null;
  return url(c.src, c.opts as ResizeOptions);
}

describe("golden URLs: each storefront's current helpers, byte for byte", () => {
  it("covers every config, and no case is a changed URL", () => {
    expect(new Set(cases.map((c) => c.config))).toEqual(new Set(Object.keys(CONFIGS)));
    expect(cases.filter((c) => "before" in c)).toEqual([]);
  });

  for (const config of Object.keys(CONFIGS)) {
    it(config, () => {
      const mine = cases.filter((c) => c.config === config);
      expect(mine.length).toBeGreaterThan(0);
      const diffs = mine
        .map((c) => ({ c, got: run(c) }))
        .filter(({ c, got }) => got !== c.expected)
        .map(({ c, got }) => ({
          call: c.call,
          src: c.src,
          opts: c.opts,
          expected: c.expected,
          got,
        }));
      expect(diffs).toEqual([]);
    });
  }
});

describe("decoCdn", () => {
  const url = createImageUrl({ providers: [decoCdn()] });
  const asset = "https://assets.decocache.com/a-storefront/abc/hero.jpg";

  it("defaults fit to cover, as v7's getSrcSet and Image", () => {
    expect(url(asset, { width: 640 })).toBe(
      "https://assets.decocms.com/image?fit=cover&width=640&src=a-storefront/abc/hero.jpg",
    );
    expect(
      createImageUrl({ providers: [decoCdn({ fit: "contain" })] })(asset, { width: 640 }),
    ).toBe("https://assets.decocms.com/image?fit=contain&width=640&src=a-storefront/abc/hero.jpg");
  });

  it('resizes only Deco-hosted sources by default; "all" or a predicate widens it', () => {
    const other = "https://images.example.com/a.jpg";
    expect(url.isOptimizable(other)).toBe(false);
    expect(url(other, { width: 10 })).toBe(other);
    const all = createImageUrl({ providers: [decoCdn({ sources: "all" })] });
    expect(all(other, { width: 10 })).toBe(
      "https://assets.decocms.com/image?fit=cover&width=10&src=https://images.example.com/a.jpg",
    );
    const some = createImageUrl({
      providers: [decoCdn({ sources: (src) => src.startsWith("/") })],
    });
    expect(some.isOptimizable("/static/a.jpg")).toBe(true);
    expect(some.isOptimizable(other)).toBe(false);
  });

  it("strips the asset hosts anywhere by default (v7), or only leading ones", () => {
    const nested = "https://images.example.com/https://assets.decocache.com/a.png";
    const all = createImageUrl({ providers: [decoCdn({ sources: "all" })] });
    const leading = createImageUrl({
      providers: [decoCdn({ sources: "all", stripAssetHosts: "leading" })],
    });
    expect(all(nested, { width: 10 })).toContain("&src=https://images.example.com/a.png");
    expect(leading(nested, { width: 10 })).toContain(`&src=${nested}`);
  });

  it("keeps decoims.com URLs whole on an Azion CDN", () => {
    const azion = createImageUrl({
      providers: [decoCdn({ domain: "https://deco-assets.edgedeco.com/", sources: "all" })],
    });
    expect(azion("https://decoims.com/a/b.png", { width: 10, fit: "cover" })).toBe(
      "https://deco-assets.edgedeco.com/image?fit=cover&width=10&src=https://decoims.com/a/b.png",
    );
  });

  it("ignores numeric qualities and takes a per-call tier", () => {
    const u = createImageUrl({ providers: [decoCdn({ quality: "medium" })] });
    expect(u(asset, { width: 10, quality: 90 })).toContain("quality=medium");
    expect(u(asset, { width: 10, quality: "low" })).toContain("quality=low");
  });
});

describe("createImageUrl", () => {
  const url = createImageUrl({ providers: [decoCdn()] });

  it('returns "" for an empty src and passes data: URIs and unknown sources through', () => {
    expect(url("", { width: 1 })).toBe("");
    expect(url("data:image/png;base64,AA==", { width: 1 })).toBe("data:image/png;base64,AA==");
    expect(url("https://images.example.com/a.jpg", { width: 1 })).toBe(
      "https://images.example.com/a.jpg",
    );
    expect(url.isOptimizable("")).toBe(false);
    expect(url.isOptimizable("data:image/png;base64,AA==")).toBe(false);
  });

  it("tries providers in order; one that returns null leaves the source to the next", () => {
    const u = createImageUrl({
      providers: [
        { name: "a", match: (s) => s.endsWith(".png"), format: () => null },
        { name: "b", match: () => true, format: (s, o) => `${s}#${o.width}`, hosts: ["b.example"] },
      ],
    });
    expect(u("x.png", { width: 5 })).toBe("x.png#5");
    expect(u.hosts()).toEqual(["b.example"]);
  });

  it("lists the providers' hosts once", () => {
    expect(
      createImageUrl({
        providers: [decoCdn(), decoCdn(), decoCdn({ domain: "decoims.com" })],
      }).hosts(),
    ).toEqual(["assets.decocms.com", "decoims.com"]);
  });
});

describe("srcSet, parseSrcSet and preloadLink", () => {
  const url = createImageUrl({ providers: [decoCdn()] });
  const src = "https://assets.decocache.com/s/a.jpg";
  const at = (w: number, h?: number) =>
    `https://assets.decocms.com/image?fit=cover&width=${w}${h ? `&height=${h}` : ""}&src=s/a.jpg`;

  it("builds candidates from widths with a fixed ratio", () => {
    expect(srcSet(url, src, { widths: [100, 200], ratio: 1.5 })).toBe(
      `${at(100, 150)} 100w, ${at(200, 300)} 200w`,
    );
    expect(srcSet(url, "", { width: 100 })).toBeUndefined();
    expect(srcSet(url, src, { widths: [] })).toBeUndefined();
  });

  it("writes v7's NaN candidates when no width is given (v7's getSrcSet, byte for byte)", () => {
    const nan = "https://assets.decocms.com/image?fit=cover&width=NaN&src=s/a.jpg";
    expect(srcSet(url, src, {})).toBe(`${nan} NaNw, ${nan} NaNw`);
    expect(srcSet(url, src, { height: 300 })).toBe(
      `https://assets.decocms.com/image?fit=cover&width=NaN&height=300&src=s/a.jpg NaNw, https://assets.decocms.com/image?fit=cover&width=NaN&height=600&src=s/a.jpg NaNw`,
    );
  });

  it("parses what srcSet builds, and URLs with commas", () => {
    const set = srcSet(url, src, { width: 100, height: 100 }) as string;
    expect(parseSrcSet(set)).toEqual([
      { url: at(100, 100), w: 100 },
      { url: at(200, 200), w: 200 },
    ]);
    expect(parseSrcSet("a.jpg 1x,b,c.jpg 2x, d.jpg")).toEqual([
      { url: "a.jpg", x: 1 },
      { url: "b,c.jpg", x: 2 },
      { url: "d.jpg" },
    ]);
  });

  it("preloadLink carries href, srcset, sizes, media and a high priority", () => {
    expect(
      preloadLink(url, src, {
        width: 100,
        height: 100,
        sizes: "100vw",
        media: "(max-width: 767px)",
      }),
    ).toEqual({
      rel: "preload",
      as: "image",
      href: at(100, 100),
      imageSrcSet: `${at(100, 100)} 100w, ${at(200, 200)} 200w`,
      imageSizes: "100vw",
      media: "(max-width: 767px)",
      fetchPriority: "high",
    });
  });
});

describe("the ./image subpath", () => {
  it("package.json maps it to the source and the build", () => {
    const pkg = JSON.parse(readFileSync(new URL("../../package.json", import.meta.url), "utf-8"));
    expect(pkg.exports["./image"]).toEqual({
      types: "./dist/v8/image.d.ts",
      source: "./src/v8/image.ts",
      default: "./dist/v8/image.js",
    });
  });

  it("exports exactly the documented runtime names, none of them a commerce platform's", async () => {
    expect(Object.keys(await import("./image.ts")).sort()).toEqual([
      "createImageUrl",
      "decoCdn",
      "parseSrcSet",
      "preloadLink",
      "srcSet",
    ]);
    const source = readFileSync(new URL("./image.ts", import.meta.url), "utf-8").replace(
      /\/\*[\s\S]*?\*\//g,
      "",
    );
    expect(source).not.toMatch(/vtex|shopify|wake|magento|vteximg|myvtex/i);
  });
});
